const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const V = data[0];
const bills = [data[1], data[2], data[3]].sort((a, b) => a - b);

let count = 0;
let total = 0;

for (const bill of bills) {
  if (total + bill <= V) {
    total += bill;
    count++;
  } else {
    break;
  }
}

console.log(count);
